param(
  [string]$Url = "https://satisfactory-calculator.com/en/buildings/detail/id/Build_ManufacturerMk1_C/name/Manufacturer",
  [int]$Port = 9242
)
$ErrorActionPreference = "Stop"
$chrome = "C:\Program Files\Google\Chrome\Application\chrome.exe"
$ua = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0.0.0 Safari/537.36"
$profile = "$env:TEMP\cdp_$Port"

$proc = Start-Process $chrome -ArgumentList @(
  "--headless=new","--disable-gpu","--no-sandbox",
  "--remote-debugging-port=$Port",
  "--user-data-dir=$profile",
  "--user-agent=$ua",
  $Url
) -PassThru -WindowStyle Hidden

# poll for debug endpoint + page target
$wsUrl = $null
for ($i=0; $i -lt 40; $i++){
  Start-Sleep -Milliseconds 400
  try {
    $list = Invoke-RestMethod "http://127.0.0.1:$Port/json" -TimeoutSec 3
    $page = $list | Where-Object { $_.type -eq 'page' -and $_.webSocketDebuggerUrl } | Select-Object -First 1
    if ($page) { $wsUrl = $page.webSocketDebuggerUrl; break }
  } catch {}
}
if (-not $wsUrl) { Write-Output "ERROR: no debug endpoint"; try { $proc.Kill() } catch {}; exit 1 }

$client = New-Object System.Net.WebSockets.ClientWebSocket
$ct = [System.Threading.CancellationToken]::None
$client.ConnectAsync([Uri]$wsUrl, $ct).Wait()

function Send-Cmd($id, $method, $params){
  $obj = @{ id=$id; method=$method }
  if ($params) { $obj.params = $params }
  $json = $obj | ConvertTo-Json -Compress -Depth 6
  $bytes = [Text.Encoding]::UTF8.GetBytes($json)
  $seg = [ArraySegment[byte]]::new($bytes)
  $client.SendAsync($seg, [System.Net.WebSockets.WebSocketMessageType]::Text, $true, $ct).Wait()
}
function Recv-Until($wantId){
  $buf = [byte[]]::new(2097152)
  for ($k=0; $k -lt 200; $k++){
    $seg = [ArraySegment[byte]]::new($buf)
    $sb = New-Object Text.StringBuilder
    do {
      $r = $client.ReceiveAsync($seg, $ct); $r.Wait()
      [void]$sb.Append([Text.Encoding]::UTF8.GetString($buf, 0, $r.Result.Count))
    } while (-not $r.Result.EndOfMessage)
    $msg = $sb.ToString()
    try { $o = $msg | ConvertFrom-Json } catch { continue }
    if ($o.id -eq $wantId) { return $o }
  }
  return $null
}

Send-Cmd 1 "Runtime.enable" $null
[void](Recv-Until 1)

# wait for SPA to render: poll innerText length until stable / non-trivial
$prev = -1; $stable = 0; $text = ""
for ($t=0; $t -lt 30; $t++){
  Start-Sleep -Milliseconds 700
  Send-Cmd (100+$t) "Runtime.evaluate" @{ expression="document.body ? document.body.innerText.length : 0"; returnByValue=$true }
  $resp = Recv-Until (100+$t)
  $len = 0
  if ($resp -and $resp.result -and $resp.result.result) { $len = [int]$resp.result.result.value }
  if ($len -gt 200 -and $len -eq $prev) { $stable++ } else { $stable = 0 }
  $prev = $len
  if ($stable -ge 2) { break }
}

Send-Cmd 900 "Runtime.evaluate" @{ expression="document.body.innerText"; returnByValue=$true }
$final = Recv-Until 900
if ($final -and $final.result -and $final.result.result) { $text = [string]$final.result.result.value }

Write-Output "===URL=== $Url"
Write-Output "===TEXTLEN=== $($text.Length)"
Write-Output "===BEGIN==="
Write-Output $text
Write-Output "===END==="

try { $client.CloseAsync([System.Net.WebSockets.WebSocketCloseStatus]::NormalClosure,"bye",$ct).Wait() } catch {}
try { $proc.Kill() } catch {}

