$client.ConnectAsync([Uri]$wsUrl, $ct).Wait()
$gid = 0
function Send-Cmd($method, $params){
  $script:gid++
  $obj = @{ id=$script:gid; method=$method }
  if ($params) { $obj.params = $params }
  $json = $obj | ConvertTo-Json -Compress -Depth 6
  $bytes = [Text.Encoding]::UTF8.GetBytes($json)
  $client.SendAsync([ArraySegment[byte]]::new($bytes), [System.Net.WebSockets.WebSocketMessageType]::Text, $true, $ct).Wait()
  return $script:gid
}
function Recv-Until($wantId){
  $buf = [byte[]]::new(4194304)
  for ($k=0; $k -lt 400; $k++){
    $sb = New-Object Text.StringBuilder
    do {
      $r = $client.ReceiveAsync([ArraySegment[byte]]::new($buf), $ct); $r.Wait()
      [void]$sb.Append([Text.Encoding]::UTF8.GetString($buf, 0, $r.Result.Count))
    } while (-not $r.Result.EndOfMessage)
    try { $o = $sb.ToString() | ConvertFrom-Json } catch { continue }
    if ($o.id -eq $wantId) { return $o }
  }
  return $null
}
function Eval-JS($expr){
  $id = Send-Cmd "Runtime.evaluate" @{ expression=$expr; returnByValue=$true }
  $resp = Recv-Until $id
  if ($resp -and $resp.result -and $resp.result.result) { return $resp.result.result.value }
  return $null
}

[void](Recv-Until (Send-Cmd "Runtime.enable" $null))

$extract = @'
(function(){
  var t = document.body.innerText || "";
  if (t.indexOf("404") >= 0 && t.indexOf("Width") < 0) return "404_NOT_FOUND";
  var s = t.indexOf("Category");
  if (s < 0) { var w = t.indexOf("Width"); if (w>=0) s=w; else return "NO_DATA head="+t.substring(0,100); }
  var ends = [t.indexOf("Ingredients", s), t.indexOf("Used to craft", s), t.indexOf("An AnthorNet", s)].filter(function(x){return x>0;});
  var e = ends.length ? Math.min.apply(null, ends) : Math.min(t.length, s+450);
  return t.substring(s, e).replace(/\n{2,}/g,"\n").trim();
})()
'@

foreach ($b in $items){
  # 1) clear to about:blank to avoid stale read
  [void](Eval-JS 'location.href="about:blank"')
  for ($c=0; $c -lt 15; $c++){ Start-Sleep -Milliseconds 200; if ([int](Eval-JS 'document.body? document.body.innerText.length:0') -lt 30){break} }
  # 2) navigate to target (experimental branch)
  $url = "https://satisfactory-calculator.com/en/$($b.path)/detail/id/$($b.id)/name/$($b.name)?switchGameBranch=Experimental"
  [void](Eval-JS ("location.href=" + ('"' + $url + '"')))
  # 3) wait until Width OR 404 appears and length stabilizes
  $prev=-1; $stable=0
  for ($t=0; $t -lt 30; $t++){
    Start-Sleep -Milliseconds 500
    $len = [int](Eval-JS 'document.body? ((document.body.innerText.indexOf("Width")>=0 || document.body.innerText.indexOf("404")>=0)? document.body.innerText.length : 0):0')
    if ($len -gt 80 -and $len -eq $prev) { $stable++ } else { $stable=0 }
    $prev=$len
    if ($stable -ge 1) { break }
  }
  $block = Eval-JS $extract
  Write-Output ("##### " + $b.name + " (" + $b.id + ") [" + $b.path + "]")
  Write-Output $block
  Write-Output ""
}

try { $client.CloseAsync([System.Net.WebSockets.WebSocketCloseStatus]::NormalClosure,"bye",$ct).Wait() } catch {}
try { $proc.Kill() } catch {}

