export const meta = {
  name: 'tier7-blueprint-spatial-audit',
  description: '审查 T7 蓝图施工手册的机器占位/belt-splitter-merger分布/真实游戏可建性，逐蓝图发现问题并对抗验证',
  phases: [
    { title: 'Audit', detail: '逐 BP + 顶层文档 审查占位/物流/可建性' },
    { title: 'Verify', detail: '对抗验证每条 error/warn 发现（重算几何）' },
  ],
}

const BASE = 'G:/幸福工厂/幸福工厂设计/docs/superpowers/specs/2026-05-24-tier7-blueprints/'
const MAIN = 'G:/幸福工厂/幸福工厂设计/docs/superpowers/specs/2026-05-24-tier7-blueprint-design.md'
const README = BASE + 'README.md'

const REF = `
== 已实测确认的真实游戏数据（Satisfactory 1.1/1.2 实验版；来源 satisfactory-calculator.com + 官方 wiki.gg，已对抗验证）==
【生产建筑 占地 宽W×长L×高H(米) / 端口】(registry.ts 已确认全部正确)：
- Smelter 6×9×10  | 1 in(back) 1 out(front)
- Foundry 8×9×9   | 2 in(back) 1 out(front)
- Constructor 8×10×8 | 1 in(back) 1 out(front)
- Assembler 10×15×8 | 2 in(back@2.5,6.5) 1 out(front@4.5)
- Manufacturer 20×22×12 | 4 in(在 FRONT) 1 out(在 BACK)  ← 唯一输入在前的机器
- Refinery 10×20×31 | 1 belt-in + 1 fluid-in(back) / 1 belt-out + 1 fluid-out(front)；净高 31m！
- Blender 19×16×16 | 2 in 2 out
- Packager 8×8×12  | 2 in 2 out
- Particle-Accelerator 38×24×38 | 2 in 2 out
- Converter 16×16×16 | 2 in 2 out
【物流/储存】：
- Splitter/Merger/SmartSplitter/ProgrammableSplitter 全部 4×4×3m（=0.5×0.5 cell，高 3m）。splitter:1in3out；merger:3in1out
- Conveyor Lift: 核心 footprint 2×2m，但【实测包围盒 3.5×2m】——多出 1.5m 是进出口 bend/lip 的水平外翻；垂直高度可变【最小 4m、最大 48m】，可独立站立；1.1 起 splitter/merger 可吸附在 lift 进口/出口/中间任意点
- AWESOME Sink 16×13×24m（宽16 长13 高24）| 仅 1 个固体输入口、0 输出；【只吃固体，不接受流体】；高 24m≈3 个 cell
- Storage 5×10×4m（24格，1in1out）；Industrial-Storage 5×10×8m（48格，2in2out）
- Pipeline Mk1/Mk2 截面 2×2m，吞吐 300/600 m³/min；Pipeline Junction Cross 2×2m 四向
- Dim Depot Uploader：游戏内无独立"Uploader"建筑确证，本设计假设占地 5×10m（参照 storage），【此值未经实测，标注为待核】
【传送带 belt 物理（关键！）】：
- 吞吐 Mk1-6 = 60/120/270/480/780/1200 items/min（Mk5=780）
- 最大坡度 35°；单段最长 56m；最小可建 ~0.5m；最小转弯半径 2m；最陡升 31m垂直/45m水平
- 【belt 不能同时转弯+爬升】必须先转后爬（1.1 的 Curve 模式只做水平曲线，不解除此限制）。两端口若水平且垂直都错位，走线要把"转弯相"和"爬升相"分开，各自留独立平面净空，不能斜向螺旋省空间
== 蓝图坐标系 ==
- Mk2 蓝图 = 5×5×5 cell = 40×40×40m，1 cell=8m。机器层 0-35m，屋顶总线层 35-40m。多层堆叠每层间 4m 地基。
- ASCII 俯视图比例：横向 1 字符=1m，纵向 1 行=2m（40×40m → 40 字符 × 20 行）。col 0→5 左→右，row 0→5 上→下。
- 端口方向(facing=south 默认)：back=上(北)=输入(除 manufacturer)；front=下(南)=输出。manufacturer 反转(输入在 front)。
`

const RULES = `
== 项目布局规则（来自 CLAUDE.md，审查时据此判断）==
- R2 网格对齐 0.25 步进(2m)。R3 不越界(机器在 40×40 内)。R13 同层机器 AABB 不得重叠(边缘接触可)。
- R7 belt 路径正交无斜线。R16 belt 必须垂直进出端口(接 top/bottom 端口→最后一段垂直；接 left/right→最后一段水平)。R17 belt 实长 ≤ 起终点曼哈顿距离×1.4(否则飞天面条)。
- 同轴对齐：直连上下游机器端口应落在同一 col 或 row 主轴，让 belt 尽量直。
- 歧管(manifold)布局：同配方多台机器从主 belt 串接 splitter 逐台取料。
- 注意 CLAUDE.md 自带的"机器尺寸表"有错（如 assembler 写 9×16、manufacturer 写 18×20），以上 REF 的实测值为准。
`

const FINDINGS_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    file: { type: 'string' },
    summary: { type: 'string', description: '该文件整体评估 2-4 句' },
    findings: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false,
        properties: {
          severity: { type: 'string', enum: ['error', 'warn', 'info'] },
          category: { type: 'string', enum: ['placement', 'belt-splitter-merger', 'buildability', 'consistency', 'flow', 'dims'] },
          location: { type: 'string', description: '文件内章节/楼层/行号定位' },
          problem: { type: 'string', description: '问题是什么' },
          evidence: { type: 'string', description: '具体数字/原文引用/几何计算' },
          fix: { type: 'string', description: '建议如何修正（具体到坐标/尺寸/措辞）' },
          confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
        },
        required: ['severity', 'category', 'location', 'problem', 'evidence', 'fix', 'confidence'],
      },
    },
  },
  required: ['file', 'summary', 'findings'],
}

const VERDICT_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    verdict: { type: 'string', enum: ['confirmed', 'refuted', 'adjusted'] },
    corrected: { type: 'string', description: '若 adjusted/refuted：独立重算后的正确数字与结论' },
    note: { type: 'string', description: '验证推理（必须展示几何/数字重算）' },
  },
  required: ['verdict', 'corrected', 'note'],
}

function auditPrompt(path, name, extra) {
  return `你是 Satisfactory 工厂蓝图的空间可建性审查员。审查这一个文件：${path}

${REF}
${RULES}

【任务】完整 Read 该文件，针对以下三个重点逐条找问题（你的最终输出是结构化数据，不是给人看的散文）：

1. 机器占位(placement/dims)：
   - 用 REF 的【实测真实尺寸】核对文件里每台机器标注的尺寸是否正确（文件可能用了错的尺寸）。
   - 对每个楼层 ASCII 俯视图：按真实尺寸计算每台机器占地矩形，检查 (a) 是否全部落在 40×40m(5 cell) 内不越界；(b) 同层机器之间 AABB 是否重叠碰撞；(c) 机器净高+4m 地基堆叠是否 ≤35m 机器层；(d) ASCII 里标注的机器台数/尺寸与正文表格、与 REF 是否一致。展示你的计算。
2. belt/分流器/合流器分布(belt-splitter-merger)：
   - 屋顶总线层 splitter/merger/lift 的位置与数量是否合理、是否撞机器层、6 条 belt + 这些设备能否塞进 35-40m 的 5m 厚屋顶层(splitter 高 3m)。
   - 端口逻辑：merger(3in1out)/splitter(1in3out) 用法对不对；smart/programmable splitter 的 filter 配置；manufacturer 输入在 front 这一点有没有搞反；多实例侧墙 mount 配对是否自洽。
3. 真实游戏可建性(buildability)：
   - belt 走线是否违反【不能同时转弯+爬升】：凡是要从屋顶下到机器端口、或跨层、或端口错位的连接，检查是否需要"转弯相+爬升相"分离的净空，狭缝里塞不下就是问题。
   - Conveyor Lift：凡用到 lift 的地方，检查垂直跨度是否 ≥4m（<4m 建不了），以及 lift 的 3.5×2m 包围盒(含 lip)+ 可能吸附的 splitter 是否有水平空间。特别注意"仅 4m 余量塞 lift"这类临界情形。
   - AWESOME Sink 16×13×24m 的占位是否真的放得下（注意 16m 宽=2 cell、13m 长、24m 高≈3 层）、是否越界或撞其它建筑；残渣是流体不能进 sink/不能上 belt 这点有没有违反。
   - 同轴对齐/R16/R17：端口错位被迫绕路的地方标出来。

也可顺带记录 consistency(与其它文档/正文自相矛盾)、flow(流量/容量) 类问题，但重点是上面三项。
${extra || ''}

每条 finding 给出 severity(error=物理建不了/碰撞/越界/尺寸错; warn=可建但紧张/不规范/需实测; info=优化建议)、category、location、problem、evidence(含计算)、fix(具体修正)、confidence。没有问题的方面就不必硬凑。`
}

function verifyPrompt(path, f) {
  return `你是对抗验证员。下面是另一个审查员对文件 ${path} 提出的一条问题。请【独立】Read 该文件相关部分，自己重新计算几何/核对数字，判断这条问题是否成立。默认怀疑——只有你自己算出来确实成立才 confirmed；数字对但结论夸大则 adjusted；不成立则 refuted。

${REF}
${RULES}

【待验证问题】
- severity: ${f.severity} / category: ${f.category}
- location: ${f.location}
- problem: ${f.problem}
- evidence: ${f.evidence}
- 建议fix: ${f.fix}

请展示你自己的重算过程（机器 AABB、坐标、层高、belt 几何等），给出 verdict(confirmed/adjusted/refuted) + corrected(正确数字与结论) + note(推理)。`
}

const BP_FILES = [
  'BP01-iron-ingot.md','BP02-iron-base.md','BP03-screw.md','BP04-steel-ingot.md',
  'BP05-steel-beam-pipe.md','BP06-copper-smelt.md','BP07-wire-cable.md','BP08-circuit-board.md',
  'BP09-plastic-rubber.md','BP10-quartz-quickwire-concrete.md','BP11-sam.md','BP12-rotor-stator-motor.md',
  'BP13-frame-encased-beam.md','BP14-hmf-computer.md','BP15-crystal-osc-hsc.md',
  'BP-BUS-FILLER.md','BP-TERM-A.md','BP-TERM-B.md',
].map(f => ({ name: f.replace('.md',''), path: BASE + f }))

phase('Audit')

// 18 BP 文件：audit → 对每条 error/warn 发现做对抗验证
const perFile = await pipeline(
  BP_FILES,
  f => agent(auditPrompt(f.path, f.name), { label: 'audit:' + f.name, phase: 'Audit', schema: FINDINGS_SCHEMA }),
  (res, f) => {
    if (!res || !res.findings) return { file: f.name, summary: res ? res.summary : 'no result', findings: [] }
    const toVerify = res.findings.filter(x => x.severity === 'error' || (x.severity === 'warn' && x.confidence !== 'low'))
    if (!toVerify.length) return { file: f.name, summary: res.summary, findings: res.findings.map(x => ({ ...x, verify: null })) }
    return parallel(toVerify.map(fd => () =>
      agent(verifyPrompt(f.path, fd), { label: 'verify:' + f.name, phase: 'Verify', schema: VERDICT_SCHEMA })
        .then(v => ({ ...fd, verify: v }))
        .catch(() => ({ ...fd, verify: null }))
    )).then(verified => {
      const merged = res.findings.map(orig => {
        const v = verified.find(x => x.location === orig.location && x.problem === orig.problem)
        return v || { ...orig, verify: null }
      })
      return { file: f.name, summary: res.summary, findings: merged }
    })
  }
)

// 跨文档一致性 + 主文档空间审查（与 per-file 并行收尾）
const extras = await parallel([
  () => agent(
    `审查【跨文档一致性】。Read 这三个来源并交叉比对：\n1) ${README}\n2) ${MAIN}\n3) 各 BP 文件头部（按需 Read ${BASE}BP14-hmf-computer.md、BP02-iron-base.md、BP06-copper-smelt.md、BP07-wire-cable.md、BP09-plastic-rubber.md、BP10-quartz-quickwire-concrete.md、BP15-crystal-osc-hsc.md 等多实例蓝图）。\n\n重点找三者之间互相矛盾的数字：各 BP 的【实例拆分数(几个 Mk2 a/b/c)】【物理建造机器数】【当前激活数】【楼层数/每层机器布局】是否在 README 表、主设计文档表、BP 详情文件之间一致。已知线索：BP14 在 README=2 Mk2(a/b)、主设计=2 Mk2、BP14文件=3 Mk2(a/b/c)，三者打架——请系统化找出所有这类矛盾。\n\n${REF}\n${RULES}\n\n输出结构化 findings（category 多为 consistency/dims），每条标 location（指明哪两个文档哪一处冲突）、evidence（引用双方原文数字）、fix（建议以哪个为准）。`,
    { label: 'audit:cross-doc-consistency', phase: 'Audit', schema: FINDINGS_SCHEMA }
  ),
  () => agent(
    `审查【主设计文档自身的空间/拓扑可建性】：${MAIN}（1453 行，分段 Read）。\n\n重点审查文件里【非 BP 详情文件独有】的部分：\n- §蓝图详细规格 里 BP10/BP11/BP12/BP13/BP14/BP15 的楼层布局与机器并排描述（如"2 台 manufacturer 并排=40m 刚好满宽""8 constructor+1 assembler 1F 装下"等）——按 REF 真实尺寸核对占地是否真放得下、是否给 belt/lift 留了空间。\n- §通用约定 的机器净高表/层数公式是否与 REF 一致。\n- §架构总览/集群拓扑/总线 belt 设计 的物理合理性（屋顶 6+2 belt 槽位、Wall mount 高度分配 4m/6m/24m/28m 是否冲突）。\n- §Tier8/9 扩容 里粒子加速器(38×24×38)、量子编码(22×48)塞 Mk2/Mk3 的尺寸论证是否正确。\n- §registry.ts 需添加的建筑 表里的尺寸（awesome-sink 16×13×24、uploader 5×10 等）与 REF 是否一致。\n\n${REF}\n${RULES}\n\n输出结构化 findings，location 指明章节/行号，evidence 含计算，fix 具体。`,
    { label: 'audit:main-doc-spatial', phase: 'Audit', schema: FINDINGS_SCHEMA }
  ),
])

return {
  perFile,
  crossDoc: extras[0],
  mainDoc: extras[1],
}

export const meta = {
  name: 'tier7-recheck-repaired',
  description: '对 10 个返修过的文件做从零全量复审（占位/belt/可建性/一致性）+ 对抗验证，用于重新生成报告',
  phases: [
    { title: 'Recheck', detail: '逐文件从零全量审查（当前改后版本）' },
    { title: 'Verify', detail: '对抗验证每条 error/warn 发现（重算几何）' },
  ],
}

const SPECS = 'G:/幸福工厂/幸福工厂设计/docs/superpowers/specs/'
const BPDIR = SPECS + '2026-05-24-tier7-blueprints/'

