const RULES = `
== 布局公约/规则（据此判定合规）==
机器北缩 ≥4m 留 back 进料巷（manufacturer 输入 front 在南）；每排宁少一台多一层、不得满 40m 零间隙堵死走线；ASCII 按真实长度；collect belt 走机身 front 之外不穿机身(R14)；lift 各占唯一 (col,row)、不穿其它楼层机身、跨度≥4m、跨层先水平转弯相→再垂直爬升相、两端同坐标；平面 row/col 用 cell 单位(≤5) + 安装高度单独 z=…m；同层机器/splitter AABB 不重叠(R13，边缘接触允许)、不越界(R3)；merger 3in1out 多路用级联；非等分分流用 programmable splitter；manufacturer facing=south。
`

const FILES = [
  { name: '主设计文档', path: SPECS + '2026-05-24-tier7-blueprint-design.md' },
  { name: 'BP02', path: BPDIR + 'BP02-iron-base.md' },
  { name: 'BP03', path: BPDIR + 'BP03-screw.md' },
  { name: 'BP04', path: BPDIR + 'BP04-steel-ingot.md' },
  { name: 'BP07', path: BPDIR + 'BP07-wire-cable.md' },
  { name: 'BP11', path: BPDIR + 'BP11-sam.md' },
  { name: 'BP13', path: BPDIR + 'BP13-frame-encased-beam.md' },
  { name: 'BP14', path: BPDIR + 'BP14-hmf-computer.md' },
  { name: 'BP15', path: BPDIR + 'BP15-crystal-osc-hsc.md' },
  { name: 'BP-TERM-A', path: BPDIR + 'BP-TERM-A.md' },
]

const FINDINGS_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    file: { type: 'string' },
    verdict: { type: 'string', enum: ['clean', 'minor-only', 'has-issues'], description: 'clean=无问题；minor-only=仅非阻塞绘图/措辞；has-issues=有 error/warn' },
    summary: { type: 'string' },
    findings: { type: 'array', items: {
      type: 'object', additionalProperties: false,
      properties: {
        severity: { type: 'string', enum: ['error', 'warn', 'info'] },
        category: { type: 'string', enum: ['placement', 'belt-splitter-merger', 'buildability', 'consistency', 'flow', 'dims'] },
        location: { type: 'string' }, problem: { type: 'string' }, evidence: { type: 'string' }, fix: { type: 'string' }, confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
      }, required: ['severity', 'category', 'location', 'problem', 'evidence', 'fix', 'confidence'],
    } },
  }, required: ['file', 'verdict', 'summary', 'findings'],
}
const VERDICT_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: { verdict: { type: 'string', enum: ['confirmed', 'adjusted', 'refuted'] }, corrected: { type: 'string' }, note: { type: 'string' } },
  required: ['verdict', 'corrected', 'note'],
}

function auditPrompt(f) {
  return `你是 Satisfactory 蓝图空间可建性审查员。对文件【当前版本】做**从零开始的全量审查**（不要假设之前修过什么，独立重新检查所有方面）：${f.path}

${REF}
${RULES}

完整 Read 该文件，重点三方面找问题：
1. 机器占位(placement/dims)：用真实尺寸算每台机器 AABB——是否在 40×40 内不越界、同层是否无重叠、堆叠层高≤35m、ASCII 是否按真实长度画、标注尺寸是否正确。展示计算。
2. belt/分流器/合流器分布：屋顶 splitter/merger/lift 位置数量、能否塞进 5m 屋顶层、端口逻辑(merger 3in1out)、filter、混料、是否有路数/数量自相矛盾。
3. 真实可建性：belt 是否违反「不能同时转弯+爬升」、lift 跨度是否≥4m、各 lift riser 是否占唯一 col 不穿层、collect belt 是否穿机身(R14)、sink/uploader 占位、单位是否统一(cell+z)。
另记 consistency/flow 类自相矛盾数字。

给出 verdict(clean/minor-only/has-issues) + 逐条 finding(severity/category/location/problem/evidence含计算/fix/confidence)。无问题就 findings 空、verdict=clean。纯 ASCII 绘图精度若不影响真实几何，标 info/minor。`
}
function verifyPrompt(f, fd) {
  return `对抗验证：另一审查员对 ${f.path} 提出一条问题。独立 Read 文件相关处、自己重算几何/核对数字，判断是否成立。默认怀疑。
${REF}
待验证：severity=${fd.severity} category=${fd.category} location=${fd.location}
problem: ${fd.problem}
evidence: ${fd.evidence}
给出 verdict(confirmed/adjusted/refuted)+corrected(重算后正确结论)+note(展示重算)。`
}

phase('Recheck')
const results = await pipeline(
  FILES,
  f => agent(auditPrompt(f), { label: 'recheck:' + f.name, phase: 'Recheck', schema: FINDINGS_SCHEMA })
        .then(r => ({ ...r, _name: f.name }))
        .catch(e => ({ file: f.name, _name: f.name, verdict: 'has-issues', summary: 'audit error', findings: [] })),
  (res, f) => {
    const hi = (res.findings || []).filter(x => x.severity === 'error' || (x.severity === 'warn' && x.confidence !== 'low'))
    if (!hi.length) return { name: f.name, verdict: res.verdict, summary: res.summary, findings: (res.findings || []).map(x => ({ ...x, verify: null })) }
    return parallel(hi.map(fd => () =>
      agent(verifyPrompt(f, fd), { label: 'verify:' + f.name, phase: 'Verify', schema: VERDICT_SCHEMA })
        .then(v => ({ ...fd, verify: v })).catch(() => ({ ...fd, verify: null }))
    )).then(verified => ({
      name: f.name, verdict: res.verdict, summary: res.summary,
      findings: (res.findings || []).map(o => verified.find(v => v.location === o.location && v.problem === o.problem) || { ...o, verify: null }),
    }))
  }
)

const clean = results.filter(r => !r.findings.some(x => x.severity !== 'info' && (!x.verify || x.verify.verdict !== 'refuted'))).map(r => r.name)
const withIssues = results.filter(r => r.findings.some(x => x.severity !== 'info' && (!x.verify || x.verify.verdict !== 'refuted'))).map(r => r.name)
log(`复审：clean(仅info/误报) ${clean.length}/${results.length}；仍有 error/warn：${withIssues.join(', ') || '无'}`)
return { clean, withIssues, results }

