10	  const ids = new Set<string>();
11	  const belt = scheme.belts.find(b => b.id === beltId);
12	  if (!belt) return [];
13	
14	  ids.add(beltId);
15	
16	  // lift pair 互指索引：machine id → 配对 machine id + pair id
17	  const pairedMachine = new Map<string, string>();
18	  const pairIdByMachine = new Map<string, string>();
19	  for (const p of scheme.liftPairs) {
20	    pairedMachine.set(p.bottomMachine, p.topMachine);
21	    pairedMachine.set(p.topMachine, p.bottomMachine);
22	    pairIdByMachine.set(p.bottomMachine, p.id);
23	    pairIdByMachine.set(p.topMachine, p.id);
24	  }
25	
26	  function visitMachine(machineId: string) {
27	    if (ids.has(machineId)) return false;
28	    ids.add(machineId);
29	    const pairId = pairIdByMachine.get(machineId);
30	    if (pairId) ids.add(pairId);
31	    return true;
32	  }
33	
34	  function traceUp(machineId: string) {
