function DiagramMachineRendererImpl({ machine }: Props) {
  const meta = safeGetBuildingMeta(machine.type);
  const { x, y, w, h } = machineSvgRect(machine);

  if (!isFinite(x) || !isFinite(y) || !isFinite(w) || !isFinite(h) || w <= 0 || h <= 0) {
