        x={bx + bw / 2}
        y={by + bh / 2 + (subLabel && !isSmall ? -3 : 0)}
        textAnchor="middle"
        dominantBaseline="central"
        style={{ fontSize: labelFontSize, fill: labelColor }}
      >
        {displayLabel}
      </text>
      {subLabel && !isSmall && (
