param([int]$Port=9222, [string]$Out="C:\Users\lz199\AppData\Local\Temp\shot.png", [string]$Nav="")
$ErrorActionPreference="Stop"
$list = Invoke-RestMethod "http://127.0.0.1:$Port/json" -TimeoutSec 5
$page = $list | Where-Object { $_.type -eq 'page' -and $_.url -like '*localhost:5173*' } | Select-Object -First 1
if (-not $page) { $page = $list | Where-Object { $_.type -eq 'page' -and $_.webSocketDebuggerUrl } | Select-Object -First 1 }
if (-not $page) { Write-Output "NO_PAGE"; exit 1 }
$ws = $page.webSocketDebuggerUrl
$client = New-Object System.Net.WebSockets.ClientWebSocket
$ct = [System.Threading.CancellationToken]::None
$client.ConnectAsync([Uri]$ws, $ct).Wait()
$gid = 0
function Send($method,$params){ $script:gid++; $o=@{id=$script:gid;method=$method}; if($params){$o.params=$params}; $j=$o|ConvertTo-Json -Compress -Depth 8; $b=[Text.Encoding]::UTF8.GetBytes($j); $client.SendAsync([ArraySegment[byte]]::new($b),'Text',$true,$ct).Wait(); return $script:gid }
function Recv($want){ $buf=[byte[]]::new(8388608); for($k=0;$k -lt 600;$k++){ $sb=New-Object Text.StringBuilder; do { $seg=[ArraySegment[byte]]::new($buf); $r=$client.ReceiveAsync($seg,$ct); $r.Wait(); [void]$sb.Append([Text.Encoding]::UTF8.GetString($buf,0,$r.Result.Count)) } while(-not $r.Result.EndOfMessage); try { $m=$sb.ToString()|ConvertFrom-Json } catch { continue }; if($m.id -eq $want){ return $m } } return $null }
[void](Recv (Send "Page.enable" $null))
[void](Recv (Send "Runtime.enable" $null))
if ($Nav -ne "") { [void](Recv (Send "Page.navigate" @{url=$Nav})); Start-Sleep -Seconds 3 }
# capture
$id = Send "Page.captureScreenshot" @{format="png"}
$resp = Recv $id
if ($resp -and $resp.result -and $resp.result.data) {
  [IO.File]::WriteAllBytes($Out, [Convert]::FromBase64String($resp.result.data))
  Write-Output ("SAVED " + $Out + " (" + (Get-Item $Out).Length + " bytes); url=" + $page.url)
} else { Write-Output "NO_DATA" }
try { $client.CloseAsync('NormalClosure','bye',$ct).Wait() } catch {}

