    { title: 'Impl', detail: '删 SVG + 撤 diagram 块 + 字符网格渲染接入' },
    { title: 'Verify', detail: '独立验证宽度函数/对齐逻辑/隔离性/tsc' },
  ],
}

const ROOT = 'G:/幸福工厂/幸福工厂设计'

const IS_WIDE = `
// 东亚字符宽度：CJK/假名/谚文/全角 → 宽(2格)；ASCII/box-drawing(U+2500-257F)/其它 → 窄(1格)。
// box-drawing 不在任何宽范围内，故为 1 格——这是 ASCII 框线对齐的关键。
export function isWideChar(cp) {
  return (
    (cp >= 0x1100 && cp <= 0x115F) ||  // Hangul Jamo
    (cp >= 0x2E80 && cp <= 0x303E) ||  // CJK 部首/康熙/CJK 符号标点(含 。、）
    (cp >= 0x3041 && cp <= 0x33FF) ||  // 平假名/片假名/CJK 符号
    (cp >= 0x3400 && cp <= 0x4DBF) ||  // CJK 扩展 A
    (cp >= 0x4E00 && cp <= 0x9FFF) ||  // CJK 统一表意
    (cp >= 0xA000 && cp <= 0xA4CF) ||  // 彝文
    (cp >= 0xAC00 && cp <= 0xD7A3) ||  // 谚文音节
    (cp >= 0xF900 && cp <= 0xFAFF) ||  // CJK 兼容表意
    (cp >= 0xFE30 && cp <= 0xFE4F) ||  // CJK 兼容形式
    (cp >= 0xFF00 && cp <= 0xFF60) ||  // 全角 ASCII
    (cp >= 0xFFE0 && cp <= 0xFFE6) ||  // 全角符号
    (cp >= 0x20000 && cp <= 0x3FFFD)   // CJK 扩展 B+
  );
}
`.trim()

phase('Impl')
const impl = await agent(
  `你在 git 仓库 ${ROOT}（分支 feat/engineering-rewrite）做一次返工：把之前的「SVG 示意图」方案换成「字符网格渲染 ASCII 图」。**保留 ManualView 文档站（目录树 + react-markdown）**，只换图的渲染方式。用 Edit/Write 改文件（禁止 Bash/node -e/sed 改代码文件）；PowerShell 仅 git/命令。每步合理 commit，message 结尾带 Co-Authored-By: Claude Opus 4.8 (1M context) <noreply@anthropic.com>。相对 import 无扩展名。TS strict + noUnusedLocals/noUnusedParameters 全开。react-markdown@10 + remark-gfm 已装（保留，文档站还用）。

== 背景 ==
现状（之前已实现并提交）：ManualView.tsx 用 react-markdown 渲染 docs 下 md，并把 \`\`\`diagram 围栏块经 parseDiagramBlock→DiagramView 渲染成 SVG。现在改为：删掉整条 SVG 管线，所有 fenced code block（含文档里现有的 ASCII 俯视图）改用「字符网格」渲染——每个字符一个固定宽度盒子，中文 2ch、ASCII/框线 1ch，从根上解决中文混排导致 ASCII 右边框 │ 对不齐的问题。

== 步骤 ==

### 1. 删除 SVG 管线（7 个文件 + 2 个测试）
用 \`git rm\` 删除：
- src/diagram/diagramTypes.ts
- src/diagram/diagramGeometry.ts
- src/diagram/parseDiagramBlock.ts
- src/diagram/DiagramGridRenderer.tsx
- src/diagram/DiagramMachineRenderer.tsx
- src/diagram/DiagramBeltRenderer.tsx
- src/diagram/DiagramView.tsx
- src/__tests__/diagramGeometry.test.ts
- src/__tests__/parseDiagramBlock.test.ts
（命令：\`git rm src/diagram/diagramTypes.ts src/diagram/diagramGeometry.ts ...\` 一次列全）

### 2. 撤销 BP01/BP14 内嵌的 diagram 块（保留 ASCII）
Read \`docs/superpowers/specs/2026-05-24-tier7-blueprints/BP01-iron-ingot.md\`，找到内嵌的 \`\`\`diagram ... \`\`\` 围栏块（id 含 BP01-1F 的 JSON），用 Edit 整块删除（连同它的 \`\`\`diagram 起始与 \`\`\` 结束行），保留它上方的 ASCII 俯视图不动。
同理 Read \`docs/superpowers/specs/2026-05-24-tier7-blueprints/BP14-hmf-computer.md\`，删除两个 \`\`\`diagram 块（id BP14-1F 和 BP14-2F），保留 ASCII。
（这两个 md 之前各只加过 diagram 块，没动其它内容。）

### 3. 新建东亚宽度函数 src/manual/eastAsianWidth.ts（含 TDD 测试）
先写测试 src/__tests__/eastAsianWidth.test.ts：
\`\`\`ts
import { describe, it, expect } from 'vitest';
import { isWideChar } from '../manual/eastAsianWidth';

describe('isWideChar', () => {
  it('CJK 汉字为宽', () => {
    expect(isWideChar('铁'.codePointAt(0)!)).toBe(true);
    expect(isWideChar('台'.codePointAt(0)!)).toBe(true);
  });
  it('全角中文标点为宽', () => {
    expect(isWideChar('，'.codePointAt(0)!)).toBe(true);
    expect(isWideChar('。'.codePointAt(0)!)).toBe(true);
  });
  it('ASCII 字母数字为窄', () => {
    expect(isWideChar('A'.codePointAt(0)!)).toBe(false);
    expect(isWideChar('5'.codePointAt(0)!)).toBe(false);
    expect(isWideChar(' '.codePointAt(0)!)).toBe(false);
  });
  it('box-drawing 框线为窄（对齐关键）', () => {
    for (const ch of ['─','│','┌','┐','└','┘','├','┤','┬','┴','┼']) {
      expect(isWideChar(ch.codePointAt(0)!)).toBe(false);
    }
  });
});
\`\`\`
跑 \`npx vitest run src/__tests__/eastAsianWidth.test.ts\` 预期 FAIL（模块不存在）。
然后创建 src/manual/eastAsianWidth.ts，完整内容：
\`\`\`ts
${IS_WIDE}
\`\`\`
再跑预期全 PASS。

### 4. 新建 src/manual/AsciiBlock.tsx（字符网格组件）
完整内容：
\`\`\`tsx
import { memo } from 'react';
import { isWideChar } from './eastAsianWidth';

interface Props {
  text: string;
}

/** 把一段文本逐字符渲染成固定宽度盒子：中文 2ch、ASCII/框线 1ch，逐格对齐。 */
function AsciiBlockImpl({ text }: Props) {
  const lines = text.replace(/\\n$/, '').split('\\n');
  return (
    <pre className="ascii-grid">
      {lines.map((line, i) => (
        <div className="ascii-row" key={i}>
          {Array.from(line).map((ch, j) => {
            const cp = ch.codePointAt(0) ?? 0;
            return (
              <span key={j} className={isWideChar(cp) ? 'cw2' : 'cw1'}>
                {ch}
              </span>
            );
          })}
        </div>
      ))}
    </pre>
  );
}

export const AsciiBlock = memo(AsciiBlockImpl);
\`\`\`
注意：用 Array.from(line) 而非 line.split('') 以正确处理代理对（emoji/扩展汉字）。

### 5. 改 ManualView.tsx：去掉 SVG，改用自定义 pre 组件渲染所有 fenced code 为 AsciiBlock
Read 现有 src/manual/ManualView.tsx。做这些改动：
- 删除 import 行：\`import { parseDiagramBlock } from '../diagram/parseDiagramBlock';\` 和 \`import { DiagramView } from '../diagram/DiagramView';\`
- 新增 import：\`import { AsciiBlock } from './AsciiBlock';\`
- 删除原 CodeBlock 组件里拦截 language-diagram → DiagramView 的逻辑。
- 改为：用自定义 \`pre\` 组件把所有 fenced code block 渲染成 AsciiBlock。react-markdown v10 里 fenced block 是 \`<pre><code>文本</code></pre>\`，自定义 pre 组件可从其 children(code 元素) 取文本。inline code 不经 pre，保持默认。
  把 MD_COMPONENTS 改为（用这段替换原 CodeBlock + MD_COMPONENTS）：
\`\`\`tsx
import type { ComponentProps, ReactElement } from 'react';

// fenced code block：react-markdown 渲染为 <pre><code>…</code></pre>。
// 自定义 pre 取出 code 文本，交给 AsciiBlock 做字符网格对齐。
function PreBlock(props: ComponentProps<'pre'>) {
  const child = props.children as ReactElement<{ children?: unknown }> | undefined;
  const codeText = child && child.props ? child.props.children : undefined;
  const raw = String(codeText ?? '');
  return <AsciiBlock text={raw} />;
}

const MD_COMPONENTS = { pre: PreBlock };
\`\`\`
（删掉原来 \`const MD_COMPONENTS = { code: CodeBlock }\` 及 CodeBlock 函数和它用到的 ComponentProps 旧 import——把 ComponentProps/ReactElement 的 import 合并到顶部已有的 react import 里，避免重复 import 报错。）
- 保留 ReactMarkdown 调用 \`<ReactMarkdown remarkPlugins={[remarkGfm]} components={MD_COMPONENTS}>{content}</ReactMarkdown>\` 不变（只是 components 内容换了）。
- 确认不再有任何对 ../diagram/* 的 import（grep 自查）。

### 6. manual.css 加字符网格样式 + 删 diagram 相关样式
Read src/manual/manual.css。删除 diagram 专用样式块（.diagram-figure / .diagram-caption / .diagram-svg / .diagram-port / .diagram-zone-label / .diagram-note / .diagram-error-card / .diagram-error-title / .diagram-error-raw 以及 :root 里的 --diagram-default/--diagram-unknown），它们已无用。
在文件末尾追加字符网格样式：
\`\`\`css
