  for (var g of grids) { if (g.textContent.indexOf('┐') >= 0) { target = g; break; } }
  if(!target) return { ok:false };
  var rows = target.querySelectorAll('.ascii-row');
  var xs = [];
  for (var r of rows) {
    var spans = r.querySelectorAll('span');
    for (var k = spans.length-1; k>=0; k--) {
      if (spans[k].textContent === '│') { xs.push(Math.round(spans[k].getBoundingClientRect().left)); break; }
