  }
  // 统计众数对齐：多少行的右边框 x 相同
  var counts = {};
  xs.forEach(x=>counts[x]=(counts[x]||0)+1);
  var max = Math.max(...Object.values(counts));
  return { ok:true, gridCount: grids.length, rows: xs.length, alignedRows: max, distinctX: Object.keys(counts).length };
