export const meta = {
  name: 'ascii-align-fix-d',
  description: '修复 ASCII 对齐：框线/拉丁走普通 pre 流（连续无缝），仅 CJK 锁 2ch 盒子；放开正文容器宽度限制',
  phases: [
    { title: 'Fix', detail: '改 AsciiBlock 为方案D + 放开 manual.css 宽度' },
    { title: 'Verify', detail: '代码级核验 + tsc' },
  ],
}

const ROOT = 'G:/幸福工厂/幸福工厂设计'

const ASCII_BLOCK = String.raw`// src/manual/AsciiBlock.tsx
import { memo, type ReactNode } from 'react';
import { isWideChar } from './eastAsianWidth';

interface Props {
  text: string;
}

/**
 * 方案 D：框线/拉丁/数字/空格保持在 <pre white-space:pre> 文本流里（连续无缝，
 * 终端式渲染），仅把 CJK 宽字符单独包成 width:2ch 的 inline-block 盒子锁死宽度。
 * 这样：框线连续不裂缝 + 中文恒占 2 格 + 右边框逐列对齐，且不依赖具体字体。
 */
function renderLine(line: string, lineIdx: number): ReactNode[] {
  const nodes: ReactNode[] = [];
  let buf = '';
  let k = 0;
  for (const ch of Array.from(line)) {
    const cp = ch.codePointAt(0) ?? 0;
    if (isWideChar(cp)) {
      if (buf) {
        nodes.push(buf);
        buf = '';
      }
      nodes.push(
        <span key={'w' + lineIdx + '-' + k} className="cjk2">
          {ch}
        </span>,
      );
      k++;
    } else {
      buf += ch;
    }
  }
  if (buf) nodes.push(buf);
  return nodes;
}

function AsciiBlockImpl({ text }: Props) {
  const lines = text.replace(/\n$/, '').split('\n');
  return (
    <pre className="ascii-pre">
      {lines.map((line, i) => (
        <span key={i}>
          {renderLine(line, i)}
          {i < lines.length - 1 ? '\n' : ''}
        </span>
      ))}
    </pre>
  );
}

export const AsciiBlock = memo(AsciiBlockImpl);
`

phase('Fix')
const fix = await agent(
  '你在 git 仓库 ' + ROOT + '（分支 feat/engineering-rewrite）修复 ASCII 图对齐方案。用 Write/Edit 改文件（禁止 Bash/node -e/sed 改代码）；PowerShell 仅 git/命令。commit 结尾带 Co-Authored-By: Claude Opus 4.8 (1M context) <noreply@anthropic.com>。TS strict + noUnusedLocals/noUnusedParameters 全开。\n\n背景：现有 src/manual/AsciiBlock.tsx 把【每个字符】都套 inline-block 1ch/2ch 盒子，导致 box-drawing 框线之间出现裂缝（框线字形不撑满盒子 + 亚像素）。现改为【方案 D】：只有 CJK 宽字符套 2ch 盒子，其余字符（含框线/拉丁/数字/空格）留在普通 <pre white-space:pre> 文本流里连续渲染。src/manual/eastAsianWidth.ts 的 isWideChar 已存在、复用不动。\n\n## 步骤 1：用下面完整内容【整体替换】 src/manual/AsciiBlock.tsx（用 Write 覆盖）：\n\n' + ASCII_BLOCK + '\n\n## 步骤 2：改 src/manual/manual.css\n(a) Read 现有 manual.css。\n(b) 把旧的字符网格样式块整段删除：即 .ascii-grid / .ascii-row / .ascii-grid span / .ascii-grid .cw1 / .ascii-grid .cw2 这些规则（上一版方案的，全删）。\n(c) 在文件末尾追加新的 .ascii-pre 样式（方案 D）：\n\n.ascii-pre {\n  font-family: var(--font-mono);\n  font-size: 12.5px;\n  line-height: 1.55;\n  white-space: pre;\n  tab-size: 4;\n  overflow-x: auto;\n  background: var(--bg-canvas);\n  border: 1px solid var(--border-subtle);\n  border-radius: 6px;\n  padding: 12px 14px;\n  margin: 12px 0;\n  color: var(--text-primary);\n}\n.ascii-pre .cjk2 {\n  display: inline-block;\n  width: 2ch;\n  text-align: left;\n  vertical-align: baseline;\n}\n\n(d) 放开正文容器宽度限制：找到 .manual-content 规则里的 max-width: 980px，改为 max-width: none;（其余 padding/overflow/line-height 保持）。\n\n## 步骤 3：验证 + commit\n- npx tsc --noEmit -p tsconfig.app.json：本次文件 0 error（预存在的 schema.test.ts/unified-base.json 报错与本次无关，不要动）。\n- 单个 commit，message：fix(manual): ASCII 框线走 pre 流仅 CJK 锁 2ch，消除框线裂缝；放开正文宽度\n\n完成后报告：AsciiBlock 替换确认、manual.css 三处改动（删旧网格样式/加 .ascii-pre/.manual-content max-width→none）、tsc 结果、commit SHA。状态用 DONE/DONE_WITH_CONCERNS/NEEDS_CONTEXT/BLOCKED 开头。'
  , { label: 'fix:ascii-d', phase: 'Fix' }
)

phase('Verify')
const V = {
  type: 'object', additionalProperties: false,
  properties: {
    pass: { type: 'boolean' },
    onlyCjkBoxed: { type: 'boolean', description: 'AsciiBlock 是否只对 isWideChar 字符套 span，其余进 pre 文本流' },
    cssClean: { type: 'boolean', description: '旧 .ascii-grid/.cw1/.cw2 已删、新 .ascii-pre/.cjk2 已加、.manual-content max-width 已放开' },
    tscClean: { type: 'boolean' },
    issues: { type: 'array', items: { type: 'string' } },
    recommendation: { type: 'string' },
  },
  required: ['pass', 'onlyCjkBoxed', 'cssClean', 'tscClean', 'issues', 'recommendation'],
}
const verify = await agent(
  '独立核验 ' + ROOT + ' 刚做的 ASCII 对齐方案 D 修复。Read src/manual/AsciiBlock.tsx（确认：只有 isWideChar(cp) 为真的字符被包成 <span class=cjk2>，连续的非宽字符合并为纯文本节点进入 <pre white-space:pre> 流；Array.from 处理代理对；行用 \\n 连接）。Read src/manual/manual.css（确认旧 .ascii-grid/.ascii-row/.cw1/.cw2 已删，新 .ascii-pre + .ascii-pre .cjk2{width:2ch} 已加，.manual-content 的 max-width 已改为 none）。跑 npx tsc --noEmit -p tsconfig.app.json（预存在 unified-base.json 报错不计）。判断方案 D 是否能消除框线裂缝（框线在 pre 流连续渲染、CJK 锁 2ch）。给出 pass + 各布尔 + issues + recommendation。',
  { label: 'verify:ascii-d', phase: 'Verify', agentType: 'Plan', schema: V }
)

return { fix, verify }

