/* ============================================================
   Factory Plan — Industrial Blueprint Dark Theme
   ============================================================ */
@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600&display=swap');

/* 1. Reset */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* 2. CSS Variables */
:root {
  /* Base palette — 对比度校准：muted 在 bg-secondary 上至少 4.5:1 */
  --bg-primary: #0c1017;
  --bg-secondary: #121a25;
  --bg-canvas: #080c12;
  --bg-hover: rgba(40, 56, 80, 0.5);
  --bg-active: rgba(0, 188, 212, 0.1);
  --border: #293a4d;
  --border-subtle: #1f3044;
  --text-primary: #e4ecf4;
  --text-secondary: #90c8e8;
  --text-muted: #6b8299;
  --accent: #00bcd4;

  /* Machine colors */
  --smelter: #ff6b35;
  --foundry: #ff8f00;
  --constructor: #00bcd4;
  --assembler: #ce93d8;
  --manufacturer: #ef5350;
  --storage: #8d6e63;
  --industrial-storage: #a1887f;
  --splitter: #ffd740;
  --merger: #69f0ae;
  --lift: #66bb6a;

  /* Material colors */
  --mat-iron-ore: #a0782c;
  --mat-iron-ingot: #ff6b35;
  --mat-iron-plate: #00bcd4;
  --mat-iron-rod: #448aff;
  --mat-screw: #66bb6a;
  --mat-copper-ore: #e67333;
  --mat-copper-ingot: #ff7043;
  --mat-wire: #ef5350;
  --mat-cable: #c62828;
  --mat-copper-sheet: #ff8a65;
  --mat-limestone: #bdbdbd;
  --mat-concrete: #9e9e9e;
  --mat-reinforced-plate: #00838f;
  --mat-rotor: #7c4dff;
  --mat-modular-frame: #aa00ff;

  /* Functional */
  --power: #ffd740;
  --walkable: #1b5e20;
  --highlight: rgba(255, 255, 255, 0.2);

