() => {
  const items = Array.from(document.querySelectorAll('.manual-doc-item'));
  const bp01 = items.find(b => b.textContent.indexOf('BP01') >= 0);
  if (bp01) bp01.click();
  return { bp01Clicked: !!bp01 };
}

() => {
  const pres = Array.from(document.querySelectorAll('.ascii-pre'));
  let target = pres.find(p => p.textContent.indexOf('┐') >= 0) || pres[0];
  if (!target) return { ok:false, preCount: pres.length };
  target.scrollIntoView({ block: 'start' });
  // 测一行内框线 │ 的 x 间距是否均匀（无裂缝）
  const rows = target.querySelectorAll('span');
  return { ok:true, preCount: pres.length, hasGrid: !!target };
}

() => {
  const pre = [...document.querySelectorAll('.ascii-pre')].find(p => p.textContent.indexOf('┐') >= 0);
  if (!pre) return { ok: false };
  const lineSpans = [...pre.children].filter(c => c.tagName === 'SPAN');
  // 只取含框线 │ 的行（图主体），测其渲染宽度是否一致（右边框对齐）
  const frameLines = lineSpans.filter(s => s.textContent.indexOf('│') >= 0);
  const widths = frameLines.map(s => Math.round(s.getBoundingClientRect().width)).filter(w => w > 0);
  const counts = {};
  widths.forEach(w => counts[w] = (counts[w] || 0) + 1);
  const sorted = Object.entries(counts).sort((a, b) => b[1] - a[1]);
  // 验证 CJK=2×ASCII：测一段连续 ─ 的单字符宽 vs 一个中文 span 宽
  const cjk = pre.querySelector('.cjk2');
  const cjkW = cjk ? Math.round(cjk.getBoundingClientRect().width * 10) / 10 : null;
  return {
    ok: true,
    frameLineCount: widths.length,
    distinctWidths: Object.keys(counts).length,
    modeWidthPx: +sorted[0][0],
    modeLineCount: sorted[0][1],
    allWidths: sorted.map(([w, c]) => w + 'px×' + c),
    cjkSpanWidthPx: cjkW,
  };
}

input.script:
export const meta = {
  name: 'font-size-bump',
  description: '全局 UI 字体温和放大（最小 12px，整体 +1~2px），SVG 图内标签不动',
  phases: [
    { title: 'Bump', detail: '按映射放大 theme.css/manual.css/tsx 的 HTML UI 字号' },
    { title: 'Verify', detail: '核验最小≥12、SVG 未动、tsc' },
  ],
}
const ROOT = 'G:/幸福工厂/幸福工厂设计'

const RULES = `
== 字体放大规则 ==
目标：HTML UI 字体整体温和放大，最小不低于 12px；SVG 图内标签保持不动。

【放大映射】（只对 HTML UI 选择器/inline 应用）：
  8px→12px、9px→12px、10px→12px、11px→13px、12px→13px、12.5px→14px、13px→14px、14px→15px、15px→16px、16px→17px、18px→19px、22px→23px、24px→26px。
  （rem/em 相对值不动——它们相对 body 自动放大。）

【SVG 图内标签——一律不动】凡 font-size 所在 CSS 选择器属于"画在 <svg> 里的图元文字"，跳过不改。判定：选择器名含以下语义即视为 SVG，不动——
  machine-label / machine-sublabel / machine-name / port（port-dot/port-label）/ belt-label / belt-flow / flow-label / zone-label / grid-label / lift（lift 文字）/ 任何明显是机器框内/belt 上/网格刻度/区域名 的标签。
  其余（topbar/toolbar/panel/sidebar/legend/list/item/tooltip/detail/bottombar/status/badge/正文/标题/按钮 等 HTML UI）→ 按映射放大。
  注意：同一数值（如 9px）在 SVG 标签里不动、在 UI 选择器里放大——必须逐条按【选择器语义】判断，不能全局替换数值。
`

phase('Bump')
const bump = await agent(
  '你在 git 仓库 ' + ROOT + '（分支 feat/engineering-rewrite）做全局 UI 字体温和放大。用 Edit 改文件（禁止 Bash/sed 改代码）；PowerShell 仅 git/命令。commit 结尾带 Co-Authored-By: Claude Opus 4.8 (1M context) <noreply@anthropic.com>。\n\n' + RULES + '\n\n## 步骤\n### 1. src/styles/theme.css\nRead 全文。对每一处 font-size（约 60 处，行号见下参考但以实际为准：135,159,173,206,286,308,338,422,450,524,538,566,575,611,642,660,682,750,758,778,785,841,849,886,893,906,932,951,956,995,1006,1015,1024,1040,1049,1069,1081,1104 等），先看它所在的 CSS 选择器名，判定是 SVG 图内标签还是 HTML UI：\n- SVG 图内标签（machine-label/sublabel、port、belt-label、flow-label、zone-label、grid-label、lift 文字等）→ **不动**。\n- HTML UI → 按映射放大。\n另外把 body 的 font-size:13px 改 14px。\n用多次 Edit 精确改（每处带足够上下文定位）。\n\n### 2. src/manual/manual.css\nRead 全文。这些都是文档站 HTML UI，按映射放大：\n- .manual-sidebar-title 11→13；.manual-doc-item 12→13；.manual-content pre 13→14；.manual-content h3 15→16、h2 18→19、h1 22→23；.ascii-pre 12.5→14。\n- .manual-content code 的 0.88em 相对值不动。.ascii-pre .cjk2 的 width:2ch 不动（相对字号自动等比，对齐保持）。\n\n### 3. tsx inline（仅这两处 HTML，SVG renderer 的 fontSize 不动）\n- src/views/LinkedFloorView.tsx 的 fontSize: 11 → 13（先 Read 确认它是 HTML 文字而非 SVG；若是 SVG 文字则不动并说明）。\n- src/renderers/FlowTooltip.tsx 的 fontSize: 12 → 13（FlowTooltip 是 HTML 浮层）。\n- **不要动**：MachineRenderer.tsx(fontSize 7)、BeltLabelLayer.tsx(7)、LiftRenderer.tsx(5.5/4.5) —— 这些是 SVG 图内文字。AppErrorFallback/ViewErrorFallback 用 rem/em，不动。\n\n### 4. 验证 + commit\n- npx tsc --noEmit -p tsconfig.app.json：本次文件 0 error（预存在 schema.test.ts/unified-base.json 报错无关，不动）。\n- 合理分组 commit（如：theme.css UI 字号放大 / manual.css+tsx 字号放大）。\n\n完成后报告：theme.css 改了多少处 font-size、跳过多少处（列出跳过的 SVG 选择器）、body 改了没、manual.css 各处、tsx 两处、tsc 结果、commit SHA。状态用 DONE/DONE_WITH_CONCERNS/NEEDS_CONTEXT/BLOCKED 开头。'
  , { label: 'bump:fonts', phase: 'Bump' }
)

phase('Verify')
const V = {
  type: 'object', additionalProperties: false,
  properties: {
    pass: { type: 'boolean' },
    minSize12: { type: 'boolean', description: '所有被放大的 HTML UI font-size 是否都 ≥12px' },
    svgUntouched: { type: 'boolean', description: 'SVG 图内标签 font-size 是否保持原值未动' },
    tscClean: { type: 'boolean' },
    skippedSvgSelectors: { type: 'array', items: { type: 'string' } },
    issues: { type: 'array', items: { type: 'string' } },
    recommendation: { type: 'string' },
  },
  required: ['pass', 'minSize12', 'svgUntouched', 'tscClean', 'skippedSvgSelectors', 'issues', 'recommendation'],
}
const verify = await agent(
  '核验 ' + ROOT + ' 刚做的字体放大。Read src/styles/theme.css 与 src/manual/manual.css，逐条检查 font-size：(1) HTML UI 的是否都 ≥12px 且符合映射(8/9/10→12,11→12,12→13,13→14...)；(2) SVG 图内标签(machine-label/sublabel、port、belt-label、flow-label、zone-label、grid-label、lift 文字)是否保持原值未被放大；(3) body 是否 14px。Read src/views/LinkedFloorView.tsx、src/renderers/FlowTooltip.tsx 确认 inline 已放大；确认 MachineRenderer/BeltLabelLayer/LiftRenderer 的 SVG fontSize 未动。跑 npx tsc --noEmit -p tsconfig.app.json（unified-base.json 报错不计）。列出所有被跳过的 SVG 选择器。给 pass + 布尔 + issues + recommendation。',
  { label: 'verify:fonts', phase: 'Verify', agentType: 'Plan', schema: V }
)
return { bump, verify }

