  const pres = Array.from(document.querySelectorAll('.ascii-pre'));
  const target = pres.find(p => p.textContent.indexOf('┐') >= 0) || pres[0];
  if (!target) return { ok:false, preCount: pres.length };
  target.scrollIntoView({ block: 'center' });
  const r = target.getBoundingClientRect();
  const spans = [...target.children].filter(c => c.tagName==='SPAN');
  const rights = [];
  for (const s of spans){
    if (s.textContent.indexOf('│') < 0) continue;
    rights.push(Math.round(s.getBoundingClientRect().right));
  }
  const cnt={}; rights.forEach(x=>cnt[x]=(cnt[x]||0)+1);
  return {
    ok:true, preCount: pres.length,
    rect: { x:Math.round(r.x), y:Math.round(r.y), w:Math.round(r.width), h:Math.round(r.height) },
    frameLineRows: rights.length,
    distinctRightX: Object.keys(cnt).length,
    rightHistogram: cnt
  };
}

() => {
  const pres = Array.from(document.querySelectorAll('.ascii-pre'));
  const target = pres.find(p => p.textContent.indexOf('┐') >= 0) || pres[0];
  if (!target) return { ok:false };
  const lineSpans = [...target.children].filter(c => c.tagName === 'SPAN');

  // 1) 纯框线行（只含 ─│┌┐┬┴ 空格）：应 0 个 cjk2 盒子 = 纯文本连续
  // 2) 含中文行：cjk2 盒子数 = 该行中文字数；框线段是文本节点
  function analyze(span){
    const text = span.textContent.replace(/\n$/,'');
    const cjk2 = span.querySelectorAll('.cjk2').length;
    // 数该行实际中文字符数
    let cn = 0;
    for (const ch of Array.from(text)){
      const cp = ch.codePointAt(0);
      if ((cp>=0x4E00&&cp<=0x9FFF)||(cp>=0x3000&&cp<=0x303F)||(cp>=0xFF00&&cp<=0xFFEF)||(cp>=0x3400&&cp<=0x4DBF)) cn++;
    }
    const hasFrame = /[─-╿]/.test(text);
    return { cjk2Boxes: cjk2, cjkChars: cn, hasFrame, match: cjk2===cn };
  }

  // 取顶边框行、一个纯框线行、几个含中文行
  const samples = [];
  for (const s of lineSpans){
    const t = s.textContent;
    if (t.indexOf('┌────┬')>=0) samples.push({tag:'顶框', ...analyze(s)});
    else if (t.indexOf('全部 T6 通电')>=0) samples.push({tag:'含中文(全部T6通电)', ...analyze(s)});
    else if (t.indexOf('铁矿石进料')>=0) samples.push({tag:'含中文(铁矿石进料)', ...analyze(s)});
    else if (/^\s*│[\s│]*│\s*$/.test(t.replace(/\n/,''))) { /* skip */ }
  }
  // 全局：每个含中文行的 cjk2 数是否都等于其中文字数
  let allMatch = true, checkedLines = 0;
  for (const s of lineSpans){
    const a = analyze(s);
    if (a.cjkChars>0){ checkedLines++; if(!a.match) allMatch=false; }
  }
  // 框线行 cjk2 必须为 0
  let frameLinesAllPlain = true, frameLineCount=0;
  for (const s of lineSpans){
    const t = s.textContent;
    const onlyFrame = /^[\s─-╿]+\n?$/.test(t);
    if (onlyFrame){ frameLineCount++; if (s.querySelectorAll('.cjk2').length!==0) frameLinesAllPlain=false; }
  }
  return { ok:true, samples, allCjkLinesMatch: allMatch, checkedLines, frameLinesAllPlain, frameLineCount };
}

() => {
  const pre = [...document.querySelectorAll('.ascii-pre')].find(p => p.textContent.includes('┌────┬'));
  if (!pre) return { ok:false };
  const lineSpans = [...pre.children].filter(c => c.tagName === 'SPAN');
  function lastCharRight(span, ch) {
    const w = document.createTreeWalker(span, NodeFilter.SHOW_TEXT);
    let n, ln=null, li=-1;
    while (n = w.nextNode()) { const i = n.textContent.lastIndexOf(ch); if (i>=0){ ln=n; li=i; } }
    if (!ln) return null;
    const r = document.createRange(); r.setStart(ln, li); r.setEnd(ln, li+1);
    return Math.round(r.getBoundingClientRect().right);
  }
  const rows = [];
  for (const s of lineSpans) {
    const t = s.textContent.replace(/\n/g,'');
    if (!t.includes('│')) continue;
    const right = lastCharRight(s, '│');
    const hasAmbig = /[→←↑↓×·—…■□●○▲◆★°±≤≥≈]/.test(t);
    const hasCJK = /[一-鿿]/.test(t);
    rows.push({ right, hasAmbig, hasCJK, tail: t.slice(-16) });
  }
  // 分组统计 right
  const byKind = { frameOnly:[], cjkNoAmbig:[], ambig:[] };
  for (const r of rows) {
    if (r.hasAmbig) byKind.ambig.push(r.right);
    else if (r.hasCJK) byKind.cjkNoAmbig.push(r.right);
    else byKind.frameOnly.push(r.right);
  }
  const uniq = a => [...new Set(a)];
  return { ok:true,
    frameOnly_rights: uniq(byKind.frameOnly),
    cjkNoAmbig_rights: uniq(byKind.cjkNoAmbig),
    ambig_rights: uniq(byKind.ambig),
    rows
  };
}

() => {
  const pre = [...document.querySelectorAll('.ascii-pre')].find(p => p.textContent.includes('col=0'));
  if (!pre) return { ok:false, n:document.querySelectorAll('.ascii-pre').length };
  const lineSpans = [...pre.children].filter(c => c.tagName === 'SPAN');
  function lastRight(span, ch) {
    const w = document.createTreeWalker(span, NodeFilter.SHOW_TEXT);
    let n, ln=null, li=-1;
    while (n = w.nextNode()) { const i = n.textContent.lastIndexOf(ch); if (i>=0){ ln=n; li=i; } }
    if (!ln) return null;
    const r = document.createRange(); r.setStart(ln, li); r.setEnd(ln, li+1);
    return Math.round(r.getBoundingClientRect().right);
  }
  const frame=[], cjk=[], ambig=[];
  for (const s of lineSpans) {
    const t = s.textContent.replace(/\n/g,'');
    if (!t.includes('│')) continue;
    const x = lastRight(s, '│');
    if (/[→←↑↓×·—…]/.test(t)) ambig.push(x);
    else if (/[一-鿿]/.test(t)) cjk.push(x);
    else frame.push(x);
  }
  const u = a => [...new Set(a)].sort((p,q)=>p-q);
  return { frameOnly: u(frame), cjkNoAmbig: u(cjk), ambig: u(ambig) };
}

() => {
  const pre = [...document.querySelectorAll('.ascii-pre')][0];
  if (!pre) return { ok:false };
  const lineSpans = [...pre.children].filter(c => c.tagName === 'SPAN');
  function lastRight(span, ch) {
    const w = document.createTreeWalker(span, NodeFilter.SHOW_TEXT);
    let n, ln=null, li=-1;
    while (n = w.nextNode()) { const i = n.textContent.lastIndexOf(ch); if (i>=0){ ln=n; li=i; } }
    if (!ln) return null;
    const r = document.createRange(); r.setStart(ln, li); r.setEnd(ln, li+1);
    return Math.round(r.getBoundingClientRect().right);
  }
  const frame=[], cjk=[], ambig=[];
  for (const s of lineSpans) {
    const t = s.textContent.replace(/\n/g,'');
    if (!t.includes('│')) continue;
    const x = lastRight(s, '│');
    if (/[→←↑↓×·—…]/.test(t)) ambig.push(x);
    else if (/[一-鿿]/.test(t)) cjk.push(x);
    else frame.push(x);
  }
  const u = a => [...new Set(a)].sort((p,q)=>p-q);
  return { ok:true, frameOnly: u(frame), cjkNoAmbig: u(cjk), ambig: u(ambig) };
}

() => {
  const pre = document.querySelector('.ascii-pre');
  if (!pre) return { ok: false };
  const spans = Array.prototype.filter.call(pre.children, c => c.tagName === 'SPAN');
  const out = [];
  for (let i = 0; i < spans.length; i++) {
    const s = spans[i];
    const t = s.textContent.replace(/\n/g, '');
    if (t.indexOf('│') < 0) continue;
    const rects = s.getClientRects();
    const right = rects.length ? Math.round(rects[rects.length - 1].right) : null;
    const ambig = /[←-↓×·—…]/.test(t);
    const cjk = /[一-鿿]/.test(t);
    out.push(right + (ambig ? 'A' : cjk ? 'C' : 'F'));
  }
  return { ok: true, rights: out };
}

