export const meta = {
  name: 'ascii-align-research',
  description: '纯文本搜索调研：浏览器渲染含中文 ASCII box-drawing 逐列对齐的根治方案（只用 WebSearch/WebFetch，禁用浏览器）',
  phases: [
    { title: 'Search', detail: '5 角度并行 WebSearch（禁用浏览器工具）' },
    { title: 'Synthesize', detail: '综合成方案对比 + 单一推荐' },
  ],
}

const NOBROWSER = `
【硬约束】你只能用 WebSearch 和 WebFetch 两个工具做调研。**严禁使用任何浏览器/chrome-devtools 工具**（navigate_page/take_screenshot/evaluate_script/new_page 等一律禁止），不要打开任何真实浏览器标签页。如果 WebFetch 某 URL 返回 403/失败，就换 WebSearch 关键词或换源，不要回退到浏览器。
`

const ANGLES = [
  { key: 'font-dual-width', q: `调研：哪些等宽字体自带 CJK 字形且【CJK advance 严格等于 2 倍拉丁 advance】、box-drawing 字符(U+2500-257F)为单宽且与拉丁共基线对齐，可用于网页 <pre> 直接渲染含中文的 ASCII 框线图并逐列对齐。重点对比：Sarasa Mono / 更纱黑体、Noto Sans Mono CJK、Source Han Mono / 思源等宽、Cascadia Code、Maple Mono CJK、MS Gothic、GNU Unifont。每个给：是否真双宽(CJK=2×Latin)、box-drawing 是否对齐、文件体积、许可证(OFL?)、能否子集化自托管(woff2)、CDN 可用性。结论：哪个最适合"网页自托管 + 纯 pre 渲染中文 box-drawing 图逐列对齐"。` },
  { key: 'why-misalign', q: `调研：为什么浏览器里用等宽字体渲染含中文(CJK)的文本会对不齐？CSS 'ch' 单位的精确定义('0' 字形的 advance measure)。为什么用 <span style="display:inline-block;width:2ch"> 包字符会与真实字形 advance 产生亚像素偏差并累积？为什么 inline-block 拆字符渲染会在等宽字体下引入 subpixel gap(连纯 ASCII 行都对不齐)？CJK 字符回退(font fallback)到非等宽字体导致宽度≠2×Latin 的机制。box-drawing U+2500-257F 在等宽字体里是否保证占 1 个 advance。` },
  { key: 'terminal-eaw', q: `调研：终端模拟器(xterm.js / VS Code 集成终端 / Windows Terminal / Alacritty)如何渲染含中文的 box-drawing 字符并保证逐列对齐+框线连续？是否用 cell-based 渲染(每个 cell 固定像素、CJK 占 2 个 cell、box-drawing 占 1 cell 拉满)？Unicode East Asian Width (UAX #11) 的 Wide/Fullwidth/Ambiguous/Narrow 如何判定字符列宽？box-drawing 属于哪一类？Ambiguous 宽度字符在 CJK 上下文算 1 列还是 2 列(这是框线对齐关键)？xterm.js 的对齐机制能否搬到普通网页。` },
  { key: 'css-canvas-svg', q: `调研：在网页里精确渲染等宽 ASCII art 的几种技术路径与可靠性：(1) CSS 层面 white-space:pre + 等宽字体 + letter-spacing:0 + tab-size + font-variant-east-asian + font-feature-settings 能否保证含中文逐列对齐；(2) <canvas> 用 fillText 按固定 cell 网格逐字符绘制(measureText、CJK 占 2 cell、devicePixelRatio 缩放避免模糊)能否 100% 对齐、能否选中复制；(3) SVG <text> 逐 cell x 坐标定位的可行性。各路径优缺点、复杂度、清晰度、可访问性。` },
  { key: 'react-impl', q: `调研：React 项目里渲染含中文的 ASCII / box-drawing 工厂俯视图、要求像终端一样框线连续+逐列对齐，社区的最佳实践与现成库。关键词：react ascii art monospace CJK alignment, render box-drawing in browser, monospace CJK double width web, self-host Sarasa Mono woff2 subset, xterm.js render static text。是否有人用"自托管真双宽等宽字体 + 纯 pre"成功？canvas 渲染 ascii 的 React 组件库？关键实现要点与坑(woff2 子集化工具 fonttools/pyftsubset、@font-face、font-display)。` },
]

phase('Search')
const FINDING_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    angle: { type: 'string' },
    keyFindings: { type: 'array', items: { type: 'string' }, description: '该角度的关键结论，每条带来源 URL' },
    recommendation: { type: 'string', description: '该角度对最终方案的倾向性结论' },
    sources: { type: 'array', items: { type: 'string' } },
  },
  required: ['angle', 'keyFindings', 'recommendation', 'sources'],
}
const results = await parallel(ANGLES.map(a => () =>
  agent(
    `你是技术调研员。只用 WebSearch + WebFetch 调研下面这个问题，给出带来源 URL 的结论。\n\n${NOBROWSER}\n\n【调研问题】\n${a.q}\n\n做 3-6 次 WebSearch（必要时 WebFetch 打开权威页面如 MDN、Unicode.org、字体官方仓库、xterm.js 文档、CSS-Tricks、Stack Overflow 高票答案）提炼事实。每条关键结论标注来源 URL。`,
    { label: 'search:' + a.key, phase: 'Search', schema: FINDING_SCHEMA }
  ).then(r => ({ ...r, _key: a.key })).catch(e => ({ angle: a.key, keyFindings: ['FAILED: ' + String(e)], recommendation: '', sources: [], _key: a.key }))
))

phase('Synthesize')
const SYNTH_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    rootCause: { type: 'string', description: '为什么之前的方案(纯pre/逐字符ch盒子/仅CJK盒子)都对不齐——根本机制' },
    optionComparison: { type: 'array', items: {
      type: 'object', additionalProperties: false,
      properties: {
        name: { type: 'string' },
        howItWorks: { type: 'string' },
        alignsCJK: { type: 'string', description: '能否保证含中文逐列对齐+框线连续' },
        selectable: { type: 'string', description: '能否选中复制文本' },
        complexity: { type: 'string' },
        cons: { type: 'string' },
      },
      required: ['name', 'howItWorks', 'alignsCJK', 'selectable', 'complexity', 'cons'],
    } },
    recommendation: { type: 'string', description: '单一明确推荐 + 理由' },
    implementationPlan: { type: 'array', items: { type: 'string' }, description: '推荐方案的关键实现步骤（可直接指导 React 落地，含字体子集化/woff2/@font-face/CSS 细节 或 canvas cell 渲染细节）' },
    pitfalls: { type: 'array', items: { type: 'string' } },
    citations: { type: 'array', items: { type: 'string' } },
  },
  required: ['rootCause', 'optionComparison', 'recommendation', 'implementationPlan', 'pitfalls', 'citations'],
}
const synth = await agent(
  `你是技术方案架构师。下面是 5 个角度的调研结果，综合成一份"浏览器渲染含中文 ASCII box-drawing 图逐列对齐"的根治方案。\n\n${NOBROWSER}\n（综合阶段一般不需要再搜索；若某处证据不足可补 1-2 次 WebSearch，同样禁用浏览器。）\n\n【已知失败尝试】1) 纯 pre 等宽字体→中文回退非等宽、右边框右漂；2) 每字符 inline-block width:1ch/2ch→框线裂缝、连纯框线行右边界都差100+px；3) 仅中文包 2ch inline-block 其余留 pre→仍未对齐(纯框线行右边界6种值)。\n\n【场景】React 19 + Vite 项目，文档站 ManualView 用 react-markdown 渲染 md，需把 md 里的 ASCII 俯视图代码块渲染成逐列对齐、框线连续的图。本地自用为主。\n\n【5 角度调研结果】\n${JSON.stringify(results, null, 2)}\n\n输出：根本机制 + 方案对比表(字体自托管纯pre / canvas cell / SVG / 选择性盒子) + 单一推荐 + 可直接落地的实现步骤 + 坑 + 引用。推荐要明确(不要骑墙)，并说明为何它能解决"连纯框线行都对不齐"这个已实测的硬问题。`,
  { label: 'synthesize', phase: 'Synthesize', schema: SYNTH_SCHEMA }
)

return { results, synth }

