/* src/manual/manual.css —— 复用 theme.css 的 :root 变量，纯全局 CSS */

@font-face {
  font-family: "MapleGrid";
  src: url("/fonts/maple-grid.woff2") format("woff2");
  font-display: block;
  font-weight: normal;
  font-style: normal;
}

/* ===== 布局：左目录 + 右正文 ===== */
.manual-view {
  display: grid;
  grid-template-columns: 220px 1fr;
  height: 100%;
  overflow: hidden;
  background: var(--bg-primary);
  color: var(--text-primary);
}

.manual-sidebar {
  border-right: 1px solid var(--border);
  background: var(--bg-secondary);
  overflow-y: auto;
  padding: 12px 0;
}
.manual-sidebar-title {
  font-size: 13px;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  padding: 4px 16px 8px;
  text-transform: uppercase;
}
.manual-doc-item {
  display: block;
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 13px;
  padding: 6px 16px;
  cursor: pointer;
}
.manual-doc-item:hover { background: var(--bg-hover); }
.manual-doc-item.active {
  background: var(--bg-active);
  color: var(--accent);
  border-left: 2px solid var(--accent);
}

/* ===== 正文区（独立滚动容器，不被 <main> pan 干扰） ===== */
.manual-content {
  overflow-y: auto;
  padding: 24px 40px 80px;
  max-width: none;
  line-height: 1.7;
}
.manual-content h1 { font-size: 23px; margin: 0.6em 0 0.4em; }
.manual-content h2 { font-size: 19px; margin: 1.2em 0 0.4em; border-bottom: 1px solid var(--border-subtle); padding-bottom: 4px; }
.manual-content h3 { font-size: 16px; margin: 1em 0 0.3em; color: var(--text-secondary); }
.manual-content p { margin: 0.5em 0; }
.manual-content ul, .manual-content ol { padding-left: 1.4em; margin: 0.5em 0; }
.manual-content code {
  font-family: var(--font-mono);
  font-size: 0.88em;
  background: var(--bg-secondary);
  padding: 1px 4px;
  border-radius: 3px;
}
.manual-content pre {
  background: var(--bg-canvas);
  border: 1px solid var(--border-subtle);
  border-radius: 6px;
  padding: 12px;
  overflow-x: auto;
}
.manual-content pre code { background: none; padding: 0; }
.manual-content table {
