// 找"右侧悬空竖线"：行尾在主右框之后，还飘着孤立的 │（常是手画的注释引导符）
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
const DIR = 'docs/superpowers/specs/2026-05-24-tier7-blueprints';
function dw(ch){const cp=ch.codePointAt(0);return ((cp>=0x1100&&cp<=0x115f)||(cp>=0x2e80&&cp<=0x303e)||(cp>=0x3041&&cp<=0x33ff)||(cp>=0x3400&&cp<=0x4dbf)||(cp>=0x4e00&&cp<=0x9fff)||(cp>=0xac00&&cp<=0xd7a3)||(cp>=0xff00&&cp<=0xff60)||(cp>=0xffe0&&cp<=0xffe6))?2:1;}
function barCols(line){const out=[];let w=0;for(const c of line){const cw=dw(c);if(c==='│'||c==='┃')out.push(w+cw);w+=cw;}return out;}

const files = readdirSync(DIR).filter(f=>f.endsWith('.md')).sort();
let total=0, blocksWith=0;
for (const f of files){
  const lines = readFileSync(join(DIR,f),'utf8').split('\n');
  let i=0,blk=0;
  while(i<lines.length){
    if(lines[i].trimStart().startsWith('```')){
      const body=[];let j=i+1;
      while(j<lines.length&&!lines[j].trimStart().startsWith('```')){body.push([j+1,lines[j]]);j++;}
      if(body.some(([,l])=>/[┌┐]/.test(l))){
        blk++;
        // 主外框列 = 各行最右竖线列的众数（出现最多的那个）
        const rights = body.map(([,l])=>{const c=barCols(l);return c.length?c[c.length-1]:null;}).filter(x=>x!=null);
        const freq={};rights.forEach(x=>freq[x]=(freq[x]||0)+1);
        const main = Number(Object.entries(freq).sort((a,b)=>b[1]-a[1])[0]?.[0]);
        // 找：某行有竖线列 > main（即在主外框右侧还有竖线）
        const strays=[];
        for(const [ln,l] of body){
          const cols=barCols(l);
          const beyond=cols.filter(c=>c>main+1);
          if(beyond.length) strays.push([ln, beyond, l]);
        }
        if(strays.length){
          blocksWith++; total+=strays.length;
          console.log(`\n${f} 块#${blk}(主外框@col${main}): ${strays.length} 行右侧有悬空竖线`);
          for(const [ln,bey,l] of strays.slice(0,4)) console.log(`  L${ln} 竖线@${bey}: ${l.replace(/\s+$/,'').slice(-40)}`);
        }
      }
      i=j<lines.length?j+1:j;
    } else i++;
  }
}
console.log(`\n=== ${blocksWith} 个块有右侧悬空竖线，共 ${total} 行 ===`);

