async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const cl = (sel, pred) => { const el = [...document.querySelectorAll(sel)].find(pred); if (el) el.click(); return !!el; };
  cl('button', b => b.textContent.trim() === '手册'); await sleep(400);
  const ok = cl('.manual-doc-item', x => x.textContent.includes('BP13')); await sleep(1200);
  // 取含 "模块化框架" 的那张图
  const pre = [...document.querySelectorAll('.ascii-pre')].find(p => p.textContent.includes('feed manifold') || p.textContent.includes('M1*'));
  if (!pre) return { ok, found:false };
  pre.scrollIntoView({block:'start'});
  const node = pre.firstChild, text = pre.textContent;
  const lines = text.split('\n'); let pos = 0;
  // 统计每个竖线 x(left) → 出现在哪些行号
  const xRows = {};
  const nLines = lines.length;
  lines.forEach((line, li) => {
    for (let i = 0; i < line.length; i++) {
      if (line[i] === '│' || line[i]==='┐' || line[i]==='┘' || line[i]==='┌' || line[i]==='└') {
        const r = document.createRange(); r.setStart(node, pos+i); r.setEnd(node, pos+i+1);
        const x = Math.round(r.getBoundingClientRect().left);
        (xRows[x] = xRows[x] || []).push(li);
      }
    }
    pos += line.length + 1;
  });
  // 每个 x：出现行数。贯穿竖线=出现多行；零散=1~2行
  const cols = Object.entries(xRows).map(([x,rows]) => ({ x: +x, count: rows.length })).sort((a,b)=>a.x-b.x);
  return { ok, found:true, totalLines:nLines, verticalColsByX: cols };
}

