// scripts/fix-ascii-grid.mjs
// 对齐 BP 施工手册里 ASCII 俯视图每行的「最右竖线」到统一显示列，使图的右边框成一条直线。
// 关键：按竖线的【右边界显示列(endCol)】对齐，不依赖「行尾是否边框」——因为这些图的右外框
// 后面常跟盒外中文注释（如 │…│  进料巷 0-4m）。纯机械补 ─/空格，不改语义文字。
// 用法：node scripts/fix-ascii-grid.mjs            → dry-run
//       node scripts/fix-ascii-grid.mjs --write    → 写盘
//       node scripts/fix-ascii-grid.mjs --only BP02 → 仅文件名含 BP02 的
//       node scripts/fix-ascii-grid.mjs --diag BP02 → 打印每块对齐前后右框列分布

import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

const DIR = 'docs/superpowers/specs/2026-05-24-tier7-blueprints';
const WRITE = process.argv.includes('--write');
const arg = (flag) => { const i = process.argv.indexOf(flag); return i >= 0 ? process.argv[i + 1] : null; };
const ONLY = arg('--only');
const DIAG = arg('--diag');

// 东亚显示列宽：CJK/全角/假名/谚文 = 2；ASCII、box-drawing(U+2500-257F)、箭头 = 1
function dw(ch) {
  const cp = ch.codePointAt(0);
  if (
    (cp >= 0x1100 && cp <= 0x115f) || (cp >= 0x2e80 && cp <= 0x303e) ||
    (cp >= 0x3041 && cp <= 0x33ff) || (cp >= 0x3400 && cp <= 0x4dbf) ||
    (cp >= 0x4e00 && cp <= 0x9fff) || (cp >= 0xac00 && cp <= 0xd7a3) ||
    (cp >= 0xf900 && cp <= 0xfaff) || (cp >= 0xfe30 && cp <= 0xfe4f) ||
    (cp >= 0xff00 && cp <= 0xff60) || (cp >= 0xffe0 && cp <= 0xffe6)
  ) return 2;
  return 1;
}

const VBAR = new Set(['│', '┃']);
const HLINE = new Set(['─', '━', '┄', '┅', '┈', '┉', '╌', '═', '╤', '╧', '╪']);

// 该行最右竖线：返回 { idx(字符数组下标), endCol(其右边界显示列) }；无竖线返回 null
function rightBar(chars) {
  let w = 0, best = null;
  for (let i = 0; i < chars.length; i++) {
    const cw = dw(chars[i]);
    if (VBAR.has(chars[i])) best = { idx: i, endCol: w + cw };
    w += cw;
  }
  return best;
}

// 修一个 ASCII 代码块。返回 {lines, changed, R, before}
function fixBlock(rawLines) {
  const rows = rawLines.map((l) => Array.from(l));
  const bars = rows.map(rightBar);
  const ends = bars.filter(Boolean).map((b) => b.endCol);
  const before = bars.map((b) => (b ? b.endCol : null));
  if (ends.length < 2) return { lines: rawLines, changed: 0, R: null, before };
  const R = Math.max(...ends);
  // 区间保护：只对齐那些「最右竖线已接近 R」的行（认定为右外框），避免误推纯内部竖线/残行
  const GUARD = 8;
  let changed = 0;
  const out = rows.map((chars, ri) => {
    const b = bars[ri];
    if (!b) return chars.join('');
    if (b.endCol === R) return chars.join('');
    if (b.endCol < R - GUARD) return chars.join(''); // 该行没有右外框（最右竖线离 R 太远），不动
    const deficit = R - b.endCol;
    if (deficit <= 0) return chars.join('');
    const prev = chars[b.idx - 1];
    const fillCh = prev && HLINE.has(prev) ? '─' : ' ';
    chars.splice(b.idx, 0, ...Array(deficit).fill(fillCh));
    changed++;
    return chars.join('');
  });
  return { lines: out, changed, R, before };
}

function processFile(path) {
  const lines = readFileSync(path, 'utf8').split('\n');
  const result = [];
  let i = 0, totalChanged = 0;
  const reports = [];
  while (i < lines.length) {
    if (lines[i].trimStart().startsWith('```')) {
      const fenceStart = i;
      const body = [];
      let j = i + 1;
      while (j < lines.length && !lines[j].trimStart().startsWith('```')) { body.push(lines[j]); j++; }
      const hasFence = j < lines.length;
      const isBox = body.some((b) => /[┌┐└┘├┤┬┴┼│]/.test(b));
      if (isBox) {
        const { lines: fixed, changed, R, before } = fixBlock(body);
        if (DIAG) {
          const after = fixed.map((l) => { const b = rightBar(Array.from(l)); return b ? b.endCol : null; });
          const uniqB = [...new Set(before.filter((x) => x != null))].sort((a, b2) => a - b2);
          const uniqA = [...new Set(after.filter((x) => x != null))].sort((a, b2) => a - b2);
          reports.push(`  块@L${fenceStart + 1}: R=${R} 右框列 before=[${uniqB}] after=[${uniqA}] (${changed}行改)`);
        }
        if (changed > 0 && !DIAG) reports.push(`  块@L${fenceStart + 1}: ${changed} 行 → 右框对齐到第 ${R} 列`);
        totalChanged += changed;
        result.push(lines[i], ...fixed);
        if (hasFence) result.push(lines[j]);
      } else {
        result.push(lines[i], ...body);
        if (hasFence) result.push(lines[j]);
      }
      i = hasFence ? j + 1 : j;
    } else { result.push(lines[i]); i++; }
  }
  return { content: result.join('\n'), totalChanged, reports };
}

const files = readdirSync(DIR).filter((f) => f.endsWith('.md') && (!ONLY || f.includes(ONLY)) && (!DIAG || f.includes(DIAG)));
let grand = 0;
for (const f of files) {
  const path = join(DIR, f);
  const { content, totalChanged, reports } = processFile(path);
  if (totalChanged > 0 || DIAG) {
    grand += totalChanged;
    console.log(`\n${f}:${DIAG ? '' : ' 补齐 ' + totalChanged + ' 行'}`);
    reports.forEach((r) => console.log(r));
    if (WRITE && !DIAG && totalChanged > 0) { writeFileSync(path, content, 'utf8'); console.log('  ✓ 已写盘'); }
  }
}
console.log(`\n${DIAG ? 'DIAG' : WRITE ? '已写盘' : 'DRY-RUN'}：共 ${grand} 行${WRITE ? '已补齐' : '需补齐'}`);

// 诊断一个 md 里每个 ASCII 块中所有竖线 │ 的显示列位置，看哪些竖线列在各行不一致
import { readFileSync } from 'node:fs';
const path = process.argv[2];
if (!path) { console.error('用法: node scripts/diag-vlines.mjs <md路径>'); process.exit(1); }

function dw(ch) {
  const cp = ch.codePointAt(0);
  if ((cp>=0x1100&&cp<=0x115f)||(cp>=0x2e80&&cp<=0x303e)||(cp>=0x3041&&cp<=0x33ff)||
      (cp>=0x3400&&cp<=0x4dbf)||(cp>=0x4e00&&cp<=0x9fff)||(cp>=0xac00&&cp<=0xd7a3)||
      (cp>=0xf900&&cp<=0xfaff)||(cp>=0xfe30&&cp<=0xfe4f)||(cp>=0xff00&&cp<=0xff60)||
      (cp>=0xffe0&&cp<=0xffe6)) return 2;
  return 1;
}
// 返回该行所有 │ 的显示列位置数组
function barCols(line) {
  const cols = []; let c = 0;
  for (const ch of line) { c += dw(ch); if (ch === '│' || ch === '┃') cols.push(c); }
  return cols;
}

const lines = readFileSync(path, 'utf8').split('\n');
let i = 0, blk = 0;
while (i < lines.length) {
  if (lines[i].trimStart().startsWith('```')) {
    const body = []; let j = i+1;
    while (j < lines.length && !lines[j].trimStart().startsWith('```')) { body.push([j+1, lines[j]]); j++; }
    if (body.some(([,l]) => /[┌┐└┘│]/.test(l))) {
      blk++;
      console.log(`\n===== 块 #${blk} (L${i+1}) =====`);
      // 统计每个竖线列出现频次
      const freq = {};
      for (const [,l] of body) for (const c of barCols(l)) freq[c] = (freq[c]||0)+1;
      const colsSorted = Object.keys(freq).map(Number).sort((a,b)=>a-b);
      console.log(`竖线列位置→出现行数: ${colsSorted.map(c=>`${c}:${freq[c]}`).join('  ')}`);
      const nrows = body.filter(([,l])=>/│/.test(l)).length;
      console.log(`含竖线的行数: ${nrows}`);
      // 找"主竖线列"（出现≥半数行的列）= 应该贯穿对齐的列
      const major = colsSorted.filter(c => freq[c] >= nrows*0.4);
      console.log(`主竖线列(出现≥40%行): [${major.join(', ')}]  ← 这些应在每行同列贯穿`);
      // 逐行列出竖线列，标出偏离
      console.log('逐行竖线列:');
      for (const [ln, l] of body) {
        const cols = barCols(l);
        if (cols.length) console.log(`  L${ln}: [${cols.join(',')}]  ${l.replace(/\s+$/,'').slice(0,2)==='  '?'':''}`);
      }
    }
    i = j < lines.length ? j+1 : j;
  } else i++;
}

// scripts/audit-ascii.mjs — 全量审计每张 ASCII 图的对齐健康度
// 对每个代码块：检测「框架行」(主要由 box-drawing 构成的行，如 ┌┐ ├┤ └┘ 顶底分隔)
// 的右边框是否在同一列；以及块内竖线列的离散程度。输出每张图的健康标签。
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

const DIR = 'docs/superpowers/specs/2026-05-24-tier7-blueprints';

function dw(ch) {
  const cp = ch.codePointAt(0);
  if ((cp>=0x1100&&cp<=0x115f)||(cp>=0x2e80&&cp<=0x303e)||(cp>=0x3041&&cp<=0x33ff)||
      (cp>=0x3400&&cp<=0x4dbf)||(cp>=0x4e00&&cp<=0x9fff)||(cp>=0xac00&&cp<=0xd7a3)||
      (cp>=0xf900&&cp<=0xfaff)||(cp>=0xfe30&&cp<=0xfe4f)||(cp>=0xff00&&cp<=0xff60)||
      (cp>=0xffe0&&cp<=0xffe6)) return 2;
  return 1;
}
const VBAR = new Set(['│','┃']);
// 行内所有竖线的显示列(右边界)
function barCols(line) { const out=[]; let w=0; for (const c of line){ const cw=dw(c); if(VBAR.has(c)) out.push(w+cw); w+=cw; } return out; }
// 该行是否"框架行"：主要由 box-drawing 组成（去空格后 box 占比高）
function isFrameRow(line) {
  const t = line.replace(/\s/g,''); if (!t) return false;
  let box=0; for (const c of t){ const cp=c.codePointAt(0); if (cp>=0x2500&&cp<=0x257f) box++; }
  return box/[...t].length > 0.6;
}

const files = readdirSync(DIR).filter(f=>f.endsWith('.md')).sort();
const summary = { perfect:0, rightOnly:0, broken:0, total:0 };
const details = [];
for (const f of files) {
  const lines = readFileSync(join(DIR,f),'utf8').split('\n');
  let i=0, blk=0;
  while (i<lines.length) {
    if (lines[i].trimStart().startsWith('```')) {
      const body=[]; let j=i+1;
      while (j<lines.length && !lines[j].trimStart().startsWith('```')){ body.push([j+1,lines[j]]); j++; }
      if (body.some(([,l])=>/[┌┐└┘├┤┼]/.test(l))) {
        blk++; summary.total++;
        // 右边框收敛性：每行最右竖线列
        const rights = body.map(([,l])=>{const c=barCols(l); return c.length?c[c.length-1]:null;}).filter(x=>x!=null);
        const rightDistinct = new Set(rights).size;
        // 内部竖线网格健康度：统计所有竖线列，看是否聚成清晰的少数几列，还是散乱
        const allCols=[]; for (const [,l] of body) allCols.push(...barCols(l));
        const colFreq={}; allCols.forEach(c=>colFreq[c]=(colFreq[c]||0)+1);
        const cols=Object.keys(colFreq).map(Number).sort((a,b)=>a-b);
        // 相邻列差 1~2 的"漂移对"数量（同一道竖线散开的迹象）
        let driftPairs=0; for (let k=1;k<cols.length;k++) if (cols[k]-cols[k-1]<=2) driftPairs++;
        const nrow = body.filter(([,l])=>/│/.test(l)).length;
        let tag;
        if (rightDistinct<=1 && driftPairs===0) tag='✓完好';
        else if (driftPairs===0) tag='△仅右框需补('+rightDistinct+'列)';
        else tag='✗内部竖线散乱(漂移'+driftPairs+'/列'+cols.length+')';
        if (tag.startsWith('✓')) summary.perfect++; else if (tag.startsWith('△')) summary.rightOnly++; else summary.broken++;
        details.push(`${f} 块#${blk}(L${i+1},${nrow}行): ${tag}`);
      }
      i = j<lines.length ? j+1 : j;
    } else i++;
  }
}
console.log(details.join('\n'));
console.log(`\n=== 汇总：共 ${summary.total} 张图 | 完好 ${summary.perfect} | 仅右框需补 ${summary.rightOnly} | 内部散乱 ${summary.broken} ===`);

